def longest_balanced_subarray(nums):
    first_index = {0: -1}
    running = 0
    best = 0
    for i, n in enumerate(nums):
        running += 1 if n == 1 else -1
        if running in first_index:
            best = max(best, i - first_index[running])
        else:
            first_index[running] = i
    return best
